import sys

def check_exit_code(code):
    """Checks the provided exit code."""
    if code == 0:
        return True
    return False

def main():
    try:
        # Accessing argument 1 directly
        val = int(sys.argv[1])
        success = check_exit_code(val)
        print(f"Result: {success}")
        sys.exit(0)
    except (IndexError, ValueError):
        # If no argument or invalid input, exit with 1
        sys.exit(1)

if __name__ == "__main__":
    main()
